export class ToolNode<T = any> extends RunnableCallable<T, T> {
  tools: (StructuredToolInterface | DynamicTool | RunnableToolLike)[];

  handleToolErrors = true;

  trace = false;

  constructor(
    tools: (StructuredToolInterface | DynamicTool | RunnableToolLike)[],
    options?: ToolNodeOptions
  ) {
    const { name, tags, handleToolErrors } = options ?? {};
    super({ name, tags, func: (input, config) => this.run(input, config) });
    this.tools = tools;
    this.handleToolErrors = handleToolErrors ?? this.handleToolErrors;
  }

const tool = this.tools.find((tool) => tool.name === call.name);
try {
  if (tool === undefined) {
    throw new Error(`Tool "${call.name}" not found.`);
  }
  const toolCall = { ...call, type: "tool_call" } as ToolCall;
  const runtime: ToolRuntime = {
    ...config,
    state,
    toolCallId: call.id ?? "",
    config,
    context: config.context,
    store: (config.store as ToolRuntime["store"] | undefined) ?? null,
    writer: config.writer ?? config.configurable?.writer ?? null,
  };
  const output = await tool.invoke(toolCall, runtime);

  if (
    (isBaseMessage(output) && output.getType() === "tool") ||
    isCommand(output)
  ) {
    return output as ToolMessage | Command;
  }

  return new ToolMessage({
    status: "success",
    name: tool.name,
    content: typeof output === "string" ? output : JSON.stringify(output),
    tool_call_id: call.id!,
  });

} catch (e: any) {
  if (!this.handleToolErrors) throw e;

  if (isGraphInterrupt(e)) {
    // `NodeInterrupt` errors are a breakpoint to bring a human into the loop.
    // As such, they are not recoverable by the agent and shouldn't be fed
    // back. Instead, re-throw these errors even when `handleToolErrors = true`.
    throw e;
  }

  return new ToolMessage({
    status: "error",
    content: `Error: ${e.message}\n Please fix your mistakes.`,
    name: call.name,
    tool_call_id: call.id ?? "",
  });
}

